// WARNING : test generated by AI
// src/features/internships/internship_section.test.tsx
import { describe, it, expect, vi, afterEach } from 'vitest'
import { render, screen, within } from '@testing-library/react'
import '@testing-library/jest-dom/vitest'
import InternshipSection from './internship_section'
import { internship_list } from '../../data/internships'

// Mock the data so the test doesn't depend on real content
vi.mock('../../data/internships', () => ({
  internship_list: [
    {
      company: 'Acme Corp',
      short_description: 'Built internal dashboards',
      dates: 'Jun 2023 - Sep 2023',
    },
    {
      company: 'Globex',
      short_description: 'Worked on a data pipeline',
      dates: 'Jun 2024 - Sep 2024',
    },
  ],
}))

// Mock child components so we only test InternshipSection's own behavior
vi.mock('./internship', () => ({
  default: ({
    title,
    description,
    dates,
  }: {
    title: string
    description: string
    dates: string
  }) => (
    <div data-testid="internship-card">
      <span>{title}</span>
      <span>{description}</span>
      <span>{dates}</span>
    </div>
  ),
}))

vi.mock('../../components/clickable_card', () => ({
  default: ({ onSelect, children }: { onSelect: () => void; children: React.ReactNode }) => (
    <button data-testid="clickable-card" onClick={onSelect}>
      {children}
    </button>
  ),
}))

describe('InternshipSection', () => {
  afterEach(() => {
    vi.restoreAllMocks()
  })

  it('renders the section heading', () => {
    render(<InternshipSection />)

    expect(screen.getByRole('heading', { level: 2, name: 'My internships' })).toBeInTheDocument()
  })

  it('renders one list item per internship', () => {
    render(<InternshipSection />)

    expect(screen.getAllByRole('listitem')).toHaveLength(internship_list.length)
    expect(screen.getAllByTestId('internship-card')).toHaveLength(internship_list.length)
  })

  it('passes company, description and dates to each InternshipCard', () => {
    render(<InternshipSection />)

    internship_list.forEach((internship) => {
      const item = screen.getByText(internship.company).closest('li')

      expect(item).toBeInTheDocument()
      expect(item).toContainElement(screen.getByText(internship.short_description))
      expect(item).toContainElement(screen.getByText(internship.dates))
    })
  })

  it('wraps each InternshipCard in a ClickableCard', () => {
    render(<InternshipSection />)

    const clickableCards = screen.getAllByTestId('clickable-card')
    expect(clickableCards).toHaveLength(internship_list.length)

    clickableCards.forEach((card) => {
      expect(within(card).getByTestId('internship-card')).toBeInTheDocument()
    })
  })
})
